// components/my-portfolios/EditSquareProfileSidebar.tsx
"use client"

import Tag from "@/components/onboarding/Tag"

import ArrowLeft from "@/components/icons/ArrowLeft"
import ImageIcon from "@/components/icons/ImageIcon"
import SecondaryButton from "@/components/buttons/SecondaryButton"

import LinkIcon from "@/components/icons/LinkIcon"
import ShopIcon from "@/components/icons/ShopIcon"
import InstagramIcon from "@/components/icons/InstagramIcon"
import XIcon from "@/components/icons/XIcon"
import FacebookIcon from "@/components/icons/FacebookIcon"
import TumblrIcon from "@/components/icons/TumblrIcon"
import PixivIcon from "@/components/icons/PixivIcon"
import BlueskyIcon from "@/components/icons/BlueskyIcon"

// If you already have a Brush icon component, swap it in here.
function BrushStub() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M3.5 11.5C3.5 12.6 4.4 13.5 5.5 13.5C6.6 13.5 7.5 12.6 7.5 11.5C7.5 10.4 6.6 9.5 5.5 9.5C4.4 9.5 3.5 10.4 3.5 11.5Z"
        stroke="#A5A5A5"
        strokeWidth="1"
      />
      <path d="M9.25 2.75L13.25 6.75" stroke="#A5A5A5" strokeWidth="1" strokeLinecap="round" />
      <path d="M8 4L12 8" stroke="#A5A5A5" strokeWidth="1" strokeLinecap="round" />
      <path d="M6.75 5.25L10.75 9.25" stroke="#A5A5A5" strokeWidth="1" strokeLinecap="round" />
    </svg>
  )
}

type SocialLinks = {
  website?: string
  shop?: string
  instagram?: string
  x?: string
  facebook?: string
  tumblr?: string
  pixiv?: string
  bluesky?: string
}

type PreviousVend = {
  name: string
  year?: string
}

type Props = {
  backHref?: string

  bannerColor?: string
  backgroundColor?: string
  onBannerColorClick?: () => void
  onBackgroundColorClick?: () => void

  businessName?: string
  displayName?: string
  locationText?: string
  email?: string

  profileImageUrl?: string
  onProfileImageClick?: () => void

  merchTags?: string[]
  previousVends?: PreviousVend[]
  links?: SocialLinks

  onPublish?: () => void
  onOpenTab?: () => void
}

export default function EditSquareProfileSidebar({
  backHref = "/my-portfolios",

  bannerColor = "#FFFFFF",
  backgroundColor = "#F7F7F7",
  onBannerColorClick,
  onBackgroundColorClick,

  businessName = "Business Name",
  displayName = "Name",
  locationText = "City, State",
  email = "myemailaddress@konfolio.com",

  profileImageUrl,
  onProfileImageClick,

  merchTags = ["Tag", "Tag"],
  previousVends = [{ name: "Vended Event", year: "2026" }],
  links = {},

  onPublish,
  onOpenTab,
}: Props) {
  const hasAnyLinks = Object.values(links).some(Boolean)

  const normalizeUrl = (url: string) => (/^https?:\/\//i.test(url) ? url : `https://${url}`)

  const iconWrap =
    "group inline-flex items-center justify-center w-[24px] h-[24px] " +
    "transition-opacity duration-150 ease-out hover:opacity-70 rounded-[6px]"

  return (
    <aside
      className="
        w-[316px] h-[982px]
        bg-white
        px-[20px] py-[40px]
        flex flex-col
        justify-between
        items-center
        gap-[10px]
      "
    >
      {/* Frame 64 */}
      <div className="w-[276px] h-[36px] relative mx-auto">
        <div className="absolute left-0 top-[3px] w-[30px] h-[30px] flex items-center justify-center">
          <ArrowLeft href={backHref} className="w-[30px] h-[30px]" />
        </div>

        {/* Color Field */}
        <div className="absolute right-0 top-0 h-[36px] w-[98px] flex items-center justify-end gap-[5px]">
          <div className="w-[16px] h-[16px] flex items-center justify-center">
            <BrushStub />
          </div>

          <button
            type="button"
            onClick={onBannerColorClick}
            className="w-[36px] h-[36px] border border-[rgba(165,165,165,0.5)]"
            style={{ background: bannerColor }}
            aria-label="Banner color"
          />

          <button
            type="button"
            onClick={onBackgroundColorClick}
            className="w-[36px] h-[36px] border border-[rgba(165,165,165,0.5)]"
            style={{ background: backgroundColor }}
            aria-label="Background color"
          />
        </div>
      </div>

      {/* Profile */}
      <div className="w-[276px] flex flex-col items-center gap-[30px]">
        {/* Profile Picture */}
        <button
          type="button"
          onClick={onProfileImageClick}
          className="
            relative
            w-[189px] h-[189px]
            bg-white
            border-[0.5px] border-[#A5A5A5]
            rounded-[15px]
            overflow-hidden
            flex items-center justify-center
          "
          aria-label="Upload profile image"
        >
          {profileImageUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={profileImageUrl} alt="" className="w-full h-full object-cover" />
          ) : (
            <div className="flex flex-col items-center gap-[5px] w-[100px]">
              <div className="w-[52px] h-[52px] flex items-center justify-center">
                <ImageIcon />
              </div>
              <p className="m-0 w-[100px] text-center font-inter font-normal text-[11px] leading-[13px] text-[#A5A5A5]">
                Drop image here or click to open files
              </p>
            </div>
          )}
        </button>

        {/* Names */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <p className="m-0 w-full text-center font-inter font-normal text-[22px] leading-[140%] text-[#A5A5A5]">
            {businessName}
          </p>
          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[rgba(165,165,165,0.5)]">
            {displayName}
          </p>
        </div>

        {/* Social Medias */}
        <div className="w-[276px] h-[24px] flex items-center justify-center gap-[10px]">
          {hasAnyLinks ? (
            <>
              {links.website && (
                <a
                  href={normalizeUrl(links.website)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Website"
                >
                  <LinkIcon />
                </a>
              )}
              {links.shop && (
                <a
                  href={normalizeUrl(links.shop)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Shop"
                >
                  <ShopIcon />
                </a>
              )}
              {links.instagram && (
                <a
                  href={normalizeUrl(links.instagram)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Instagram"
                >
                  <InstagramIcon />
                </a>
              )}
              {links.x && (
                <a
                  href={normalizeUrl(links.x)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="X"
                >
                  <XIcon />
                </a>
              )}
              {links.facebook && (
                <a
                  href={normalizeUrl(links.facebook)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Facebook"
                >
                  <FacebookIcon />
                </a>
              )}
              {links.tumblr && (
                <a
                  href={normalizeUrl(links.tumblr)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Tumblr"
                >
                  <TumblrIcon />
                </a>
              )}
              {links.pixiv && (
                <a
                  href={normalizeUrl(links.pixiv)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Pixiv"
                >
                  <PixivIcon />
                </a>
              )}
              {links.bluesky && (
                <a
                  href={normalizeUrl(links.bluesky)}
                  target="_blank"
                  rel="noreferrer"
                  className={iconWrap}
                  aria-label="Bluesky"
                >
                  <BlueskyIcon />
                </a>
              )}
            </>
          ) : (
            <div className="w-[24px] h-[24px] flex items-center justify-center opacity-70">
              <LinkIcon />
            </div>
          )}
        </div>

        {/* Merch Tags */}
        <div className="w-[276px] flex flex-wrap justify-center content-center gap-[10px]">
          {merchTags.map((tag, i) => (
            <Tag key={`${tag}-${i}`} label={tag} />
          ))}
        </div>

        {/* Previous Vends */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            Previous Vends
          </p>

          {previousVends.slice(0, 1).map((vend, i) => (
            <p
              key={`${vend.name}-${vend.year ?? i}`}
              className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[rgba(165,165,165,0.5)]"
            >
              {vend.name}
              {vend.year ? ` ${vend.year}` : ""}
            </p>
          ))}
        </div>

        {/* Location + Email */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <div className="flex items-center justify-center gap-[5px]">
            <span className="font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              {locationText}
            </span>
          </div>

          <span className="font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            {email}
          </span>
        </div>
      </div>

      {/* Viewing Field */}
      <div className="w-[276px] h-[30px] flex items-center justify-center gap-[10px]">
        <SecondaryButton onClick={onPublish}>Publish</SecondaryButton>

        <button
          type="button"
          onClick={onOpenTab}
          className="
            w-[30px] h-[30px]
            rounded-full
            border border-[#262626]
            bg-white
            flex items-center justify-center
            transition-colors
            hover:bg-black/5
            active:bg-black/10
          "
          aria-label="Open in new tab"
        >
          <span className="text-[16px] leading-none text-[#262626]">↗</span>
        </button>
      </div>
    </aside>
  )
}
