// components/my-portfolios/EditSquareImageGrid.tsx
"use client"

import ImageIcon from "@/components/icons/ImageIcon"

type Props = {
  images?: { id: string; src?: string }[]
}

const RECOMMENDED = [
  "Your Product",
  "Most Recent Work",
  "Your Product",

  "Most Recent Work",
  "You & Table Display",
  "Most Recent Work",

  "Your Product",
  "Most Recent Work",
  "Your Product",
]

export default function EditSquareImageGrid({ images }: Props) {
  const cells =
    images && images.length > 0
      ? images.slice(0, 9)
      : Array.from({ length: 9 }).map((_, i) => ({
          id: String(i),
          src: "",
        }))

  return (
    <section className="w-[922px] h-[982px] flex flex-col items-center justify-center py-[30px]">
      {/* 922 x 922 grid */}
      <div className="w-[922px] h-[922px]">
        <div className="w-full h-full grid grid-cols-3 gap-[15px]">
          {cells.map((img, idx) => (
            <div
              key={img.id}
              className="
                relative
                rounded-[15px]
                overflow-hidden
                bg-[rgba(165,165,165,0.068)]
                shadow-[2px_4px_25px_rgba(165,165,165,0.1),
                        inset_2.14645px_2.00046px_9.24px_rgba(165,165,165,0.126),
                        inset_1.21725px_1.13446px_4.62px_rgba(165,165,165,0.126)]
              "
            >
              {/* Image */}
              {img.src ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={img.src}
                  alt=""
                  className="w-full h-full object-cover"
                />
              ) : (
                <button
                  type="button"
                  className="
                    absolute inset-0
                    flex flex-col
                    items-center
                    justify-center
                    gap-[5px]
                  "
                  aria-label={`Add image ${idx + 1}`}
                >
                  {/* Icon */}
                  <div className="w-[52px] h-[52px] flex items-center justify-center text-[#A5A5A5]">
                    <ImageIcon />
                  </div>

                  {/* Text */}
                  <div className="flex flex-col items-center gap-[7px]">
                    <p className="m-0 font-roboto text-[12px] leading-[14px] text-[#A5A5A5] text-center">
                      Recommended:
                    </p>

                    <p className="m-0 font-roboto text-[17px] leading-[20px] text-[#A5A5A5] text-center">
                      {RECOMMENDED[idx]}
                    </p>
                  </div>
                </button>
              )}
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}
